import {readFile,readdir,stat} from 'node:fs/promises';
import {resolve,dirname} from 'node:path';
import {createHash} from 'node:crypto';
const base=resolve('NeuralSkills/roles/saas/delivery-evidence'),facts=JSON.parse(await readFile(resolve(base,'delivery-audit-facts.json'),'utf8'));
const issues=[],files=await readdir(base);let jsonCount=0,links=0;
for(const file of files){const text=await readFile(resolve(base,file),'utf8');if(file.endsWith('.json')){JSON.parse(text);jsonCount++;}if(file.endsWith('.md'))for(const match of text.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)){if(/^[a-z]+:/i.test(match[1]))continue;links++;try{await stat(resolve(base,match[1]));}catch(error){issues.push(error.message);}}}
for(const p of facts.packages){const bytes=await readFile(resolve(base,'..',p.name,'evals/report.md'));if(createHash('sha256').update(bytes).digest('hex')!==p.reportSha256)issues.push('Report changed after final capture: '+p.name);}
console.log(JSON.stringify({observedAt:new Date().toISOString(),status:issues.length?'FAIL':'PASS',files:files.length,jsonFilesParsed:jsonCount,localAuditLinksChecked:links,finalReportHashesStillMatch:!issues.length,issues},null,2));
